import {validId} from './studio-schema.js';
export const wearableFields={name:{type:'string',minLength:1,maxLength:50},slot:{type:'string',enum:['hat','back','chest','wrist','garment']},width:{type:'number',minimum:.03,maximum:1},height:{type:'number',minimum:.03,maximum:1.3},depth:{type:'number',minimum:.02,maximum:.8},x:{type:'number',minimum:-.5,maximum:.5},y:{type:'number',minimum:-.3,maximum:1.3},z:{type:'number',minimum:-.6,maximum:.6},yaw:{type:'number',minimum:-Math.PI,maximum:Math.PI},tint:{type:'string',pattern:'^#[a-fA-F0-9]{6}$'}};
export function validateWearables(items){if(!Array.isArray(items)||items.length>8)throw Error('最多保留八件随身创作');const seen=new Set();return items.map(o=>{if(!o||!validId(o.id)||!validId(o.asset)||seen.has(o.id))throw Error('作品编号不正确');seen.add(o.id);for(const [k,s]of Object.entries(wearableFields)){const v=o[k];if(s.type==='number'?!(Number.isFinite(v)&&v>=s.minimum&&v<=s.maximum):typeof v!=='string'||s.enum&&!s.enum.includes(v)||s.pattern&&!new RegExp(s.pattern).test(v)||s.minLength&&v.trim().length<s.minLength||s.maxLength&&v.length>s.maxLength)throw Error('佩戴参数不正确');}if(typeof o.description!=='string'||o.description.length>1024||Object.keys(o).some(k=>!['id','asset','description',...Object.keys(wearableFields)].includes(k)))throw Error('作品描述不正确');return {...o}})}
export function nextWearables(values,p,asset,id){const items=[...(values.wearables||[])],i=items.findIndex(o=>o.id===p.target);if(p.operation!=='asset_create'&&i<0)throw Error('请说明要修改哪件作品');if(p.operation==='asset_remove')items.splice(i,1);else{const prev=i<0?{}:items[i],o={...prev,...p.wearable,id:i<0?id:prev.id,asset:asset||prev.asset,description:p.description||prev.description};if(i<0)items.push(o);else items[i]=o;}validateWearables(items);if(items.filter(o=>o.slot==='hat').length>1)throw Error('请先收起已有的新帽子，再试另一顶');return {...values,wearables:items,...(items.some(o=>o.slot==='hat')?{hat:'none',headwear:null}:{})};}
